"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[4554],{53860(e,a,n){n.r(a),n.d(a,{assets:()=>t,contentTitle:()=>c,default:()=>u,frontMatter:()=>r,metadata:()=>i,toc:()=>l});const i=JSON.parse('{"id":"learning/courses/integrating-quantum-and-high-performance-computing/next-steps","title":"Pr\xf3ximos pasos","description":"Esta lecci\xf3n explora el estado actual de la computaci\xf3n cu\xe1ntica y c\xf3mo la comunidad investigadora persigue la ventaja cu\xe1ntica.","source":"@site/i18n/es/docusaurus-plugin-content-docs/current/learning/courses/integrating-quantum-and-high-performance-computing/next-steps.mdx","sourceDirName":"learning/courses/integrating-quantum-and-high-performance-computing","slug":"/learning/courses/integrating-quantum-and-high-performance-computing/next-steps","permalink":"/learning/courses/integrating-quantum-and-high-performance-computing/next-steps","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/learning/courses/integrating-quantum-and-high-performance-computing/next-steps.mdx","tags":[],"version":"current","frontMatter":{"description":"Esta lecci\xf3n explora el estado actual de la computaci\xf3n cu\xe1ntica y c\xf3mo la comunidad investigadora persigue la ventaja cu\xe1ntica.","notebook_path":"learning/courses/integrating-quantum-and-high-performance-computing/next-steps.ipynb","sidebar_label":"Pr\xf3ximos pasos","title":"Pr\xf3ximos pasos"},"sidebar":"tutorialsSidebar","previous":{"title":"SQD y SKQD","permalink":"/learning/courses/integrating-quantum-and-high-performance-computing/sqd-skqd"},"next":{"title":"Examen | Integraci\xf3n de la computaci\xf3n cu\xe1ntica y la computaci\xf3n de alto rendimiento","permalink":"/learning/courses/integrating-quantum-and-high-performance-computing/exam"}}');var s=n(74848),o=n(28453);const r={description:"Esta lecci\xf3n explora el estado actual de la computaci\xf3n cu\xe1ntica y c\xf3mo la comunidad investigadora persigue la ventaja cu\xe1ntica.",notebook_path:"learning/courses/integrating-quantum-and-high-performance-computing/next-steps.ipynb",sidebar_label:"Pr\xf3ximos pasos",title:"Pr\xf3ximos pasos"},c="Perspectivas y direcci\xf3n futura {#future-outlook-and-direction}",t={},l=[{value:"\xbfPor qu\xe9 ahora?",id:"why-now",level:3},{value:"5.1 La visi\xf3n general",id:"51-the-big-picture",level:2},{value:"Grandes ideas",id:"big-ideas",level:2},{value:"Perspectiva de IBM para el futuro",id:"ibms-outlook-for-the-future",level:2},{value:"Resumen",id:"summary",level:2}];function d(e){const a={a:"a",h1:"h1",h2:"h2",h3:"h3",header:"header",img:"img",li:"li",p:"p",ul:"ul",...(0,o.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:["\n","\n",(0,s.jsx)(a.header,{children:(0,s.jsx)(a.h1,{id:"future-outlook-and-direction",children:"Perspectivas y direcci\xf3n futura"})}),"\n",(0,s.jsx)(a.p,{children:"Hasta ahora hemos explorado la motivaci\xf3n de por qu\xe9 la computaci\xf3n de alto rendimiento (HPC) y la computaci\xf3n cu\xe1ntica se utilizan juntas para resolver problemas cient\xedficos. Hemos definido los recursos de c\xf3mputo cl\xe1sicos y cu\xe1nticos \u2014incluyendo CPU, GPU y QPU\u2014 y explicado c\xf3mo escalarlos y gestionarlos mediante t\xe9cnicas como el escalamiento vertical y horizontal, el scheduling y la gesti\xf3n de cargas de trabajo. Adem\xe1s, hemos explorado modelos de programaci\xf3n tanto para QPU (por ejemplo, circuitos cu\xe1nticos y primitivos como Sampler y Estimator) como para computadores cl\xe1sicos, incluyendo pr\xe1cticas de programaci\xf3n paralela con MPI, una herramienta poderosa en la computaci\xf3n heterog\xe9nea cu\xe1ntico-cl\xe1sica. Finalmente, hemos estudiado y aplicado algoritmos cu\xe1nticos avanzados basados en muestreo, como la Diagonalizaci\xf3n Cu\xe1ntica Basada en Muestras (SQD) y la Diagonalizaci\xf3n Cu\xe1ntica de Krylov Basada en Muestras (SKQD). Estos algoritmos utilizan el m\xe9todo del subespacio para estimar con precisi\xf3n la energ\xeda del estado fundamental de mol\xe9culas y materiales, preparando y muestreando estados cu\xe1nticos que definen un subespacio para la diagonalizaci\xf3n cl\xe1sica, una combinaci\xf3n de diferentes modelos de programaci\xf3n en un conjunto de recursos heterog\xe9neos. Con estos conceptos fundamentales de la supercomputaci\xf3n cu\xe1ntica y cl\xe1sica, ya no hablamos de que uno reemplace al otro, sino de crear un sistema integrado y potente que trabaje sin\xe9rgicamente, una combinaci\xf3n que marcar\xe1 el comienzo de la ventaja cu\xe1ntica."}),"\n",(0,s.jsx)(a.h3,{id:"why-now",children:"\xbfPor qu\xe9 ahora?"}),"\n",(0,s.jsxs)(a.p,{children:['La comunidad ya ha superado el hito de la "utilidad cu\xe1ntica", es decir, el momento en que los computadores cu\xe1nticos fueron demostrados por primera vez como herramientas cient\xedficas \xfatiles que permiten c\xe1lculos m\xe1s all\xe1 de las simulaciones cl\xe1sicas de fuerza bruta. Esta era de utilidad comenz\xf3 con el muy citado ',(0,s.jsx)(a.a,{href:"https://www.nature.com/articles/s41586-023-06096-3",children:"art\xedculo de utilidad"}),', que apareci\xf3 en la portada de Nature en 2023, e incluy\xf3 docenas de publicaciones de socios, clientes e investigadores de IBM Quantum\xae. Hoy, el enfoque se ha desplazado al siguiente desaf\xedo crucial: alcanzar la ventaja cu\xe1ntica. Durante mucho tiempo, el t\xe9rmino "ventaja cu\xe1ntica" sufri\xf3 de definiciones imprecisas. Este ',(0,s.jsx)(a.a,{href:"https://arxiv.org/abs/2506.20658",children:"art\xedculo"})," propuso una definici\xf3n concreta que utilizamos aqu\xed. Seg\xfan esta, la ventaja cu\xe1ntica se refiere a la ejecuci\xf3n de una tarea de procesamiento de informaci\xf3n en hardware cu\xe1ntico que cumple dos criterios esenciales:"]}),"\n",(0,s.jsx)(a.p,{children:"i) La correcci\xf3n del resultado puede demostrarse rigurosamente, y"}),"\n",(0,s.jsx)(a.p,{children:"ii) La tarea se ejecuta con una superioridad cu\xe1ntica que demostrablemente ofrece mayor eficiencia, rentabilidad o precisi\xf3n que la que ser\xeda alcanzable solo con computaci\xf3n cl\xe1sica."}),"\n",(0,s.jsx)(a.p,{children:"Se espera que la ventaja cu\xe1ntica ocurra por primera vez a finales de 2026 y que esto suceda mediante el uso conjunto de recursos cu\xe1nticos y HPC. Esta lecci\xf3n describe la visi\xf3n central de este nuevo paradigma, explica las ideas clave y ofrece una perspectiva basada en un marco verificable e independiente de plataforma para la demostraci\xf3n y realizaci\xf3n de una verdadera ventaja cu\xe1ntica."}),"\n",(0,s.jsx)(a.h2,{id:"51-the-big-picture",children:"5.1 La visi\xf3n general"}),"\n",(0,s.jsx)(a.p,{children:'Por primera vez, estamos presenciando un punto de inflexi\xf3n significativo en la historia de la computaci\xf3n: la era de la supercomputaci\xf3n centrada en lo cu\xe1ntico (QCSC), un paradigma emergente que integra estrechamente procesadores cu\xe1nticos (QPU) con supercomputadores cl\xe1sicos. La visi\xf3n no es que los sistemas cu\xe1nticos reemplacen a los cl\xe1sicos, sino demostrar que esta arquitectura heterog\xe9nea \u2014donde "cu\xe1ntico m\xe1s cl\xe1sico" supera a la computaci\xf3n puramente cl\xe1sica\u2014 es el camino m\xe1s impactante hacia adelante. En este modelo, las QPU est\xe1n concebidas como coprocesadores especializados que trabajan codo con codo con CPU y GPU para abordar problemas computacionales que son intratables para los computadores cl\xe1sicos.'}),"\n",(0,s.jsx)(a.p,{children:"El potencial completo de esta nueva arquitectura solo puede aprovecharse haciendo estas poderosas herramientas accesibles al mayor n\xfamero posible de usuarios. Esta visi\xf3n ya est\xe1 tomando forma: mediante la instalaci\xf3n de sistemas cu\xe1nticos en centros de computaci\xf3n de alto rendimiento establecidos y el desarrollo de software como los plugins de Quantum-Slurm, que simplifican su integraci\xf3n en flujos de trabajo cl\xe1sicos existentes. Al hacer estos sistemas heterog\xe9neos m\xe1s accesibles para la comunidad investigadora en general, fomentamos el entorno necesario para la innovaci\xf3n y el descubrimiento."}),"\n",(0,s.jsx)(a.p,{children:"Esta estrategia \u2014tecnolog\xeda integrada combinada con una amplia base de usuarios\u2014 es el camino por el cual la comunidad alcanzar\xe1 la ventaja cu\xe1ntica en un futuro cercano. La ventaja cu\xe1ntica no es un hito \xfanico y definitivo, sino un proceso: una secuencia de demostraciones cada vez m\xe1s s\xf3lidas que son cuidadosamente evaluadas, reproducidas y cuestionadas por la comunidad hasta alcanzar un consenso cient\xedfico. Este es el camino para mostrar, a finales de 2026, los primeros casos cre\xedbles y verificables en los que esta nueva forma de computaci\xf3n resuelve problemas pr\xe1cticos de manera m\xe1s eficiente, rentable o precisa de lo que ser\xeda posible solo con computaci\xf3n cl\xe1sica."}),"\n",(0,s.jsx)(a.p,{children:(0,s.jsx)(a.img,{alt:"A diagram showing the cost of simulations as a function of increasing circuit complexity for both classical computers and quantum computers with error mitigation. Once the curves cross, the space between them corresponds to quantum advantage.",src:n(44186).A+"",width:"1491",height:"1016"})}),"\n",(0,s.jsx)(a.h2,{id:"big-ideas",children:"Grandes ideas"}),"\n",(0,s.jsx)(a.p,{children:"Para hacer realidad esta visi\xf3n, deben abordarse varias preguntas e ideas fundamentales."}),"\n",(0,s.jsxs)(a.ul,{children:["\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsx)(a.p,{children:"Partici\xf3n \xf3ptima de cargas de trabajo: En el lado del software, el desaf\xedo radica en la gesti\xf3n de flujos de trabajo h\xedbridos complejos. La orquestaci\xf3n fluida de tareas a trav\xe9s de recursos cu\xe1nticos y cl\xe1sicos requiere herramientas sofisticadas. Esto incluye middleware Quantum-HPC e infraestructuras de runtime dise\xf1adas para la planificaci\xf3n de trabajos, la gesti\xf3n de recursos y el flujo de datos en este entorno heterog\xe9neo. Adem\xe1s, el desarrollo de t\xe9cnicas para paralelizar efectivamente circuitos cu\xe1nticos o descomponerlos en partes m\xe1s peque\xf1as y manejables es crucial para maximizar la utilidad del hardware cu\xe1ntico actual."}),"\n"]}),"\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsx)(a.p,{children:'Tolerancia a fallos a nivel de sistema: La soluci\xf3n definitiva para proteger la informaci\xf3n cu\xe1ntica del ruido es la computaci\xf3n cu\xe1ntica tolerante a fallos (FTQC), donde la informaci\xf3n se codifica en "qubits l\xf3gicos" robustos. Aunque los nuevos c\xf3digos cu\xe1nticos de baja densidad de verificaci\xf3n de paridad (qLDPC) ofrecen un camino para reducir la enorme carga de recursos, la implementaci\xf3n de tolerancia a fallos completa a\xfan no es factible en el corto plazo. Simult\xe1neamente, la mitigaci\xf3n de errores utiliza posprocesamiento cl\xe1sico para reducir o eliminar sesgos en los c\xe1lculos causados por el ruido, siendo tambi\xe9n un elemento cr\xedtico para alcanzar sistemas cu\xe1nticos tolerantes a fallos a nivel de sistema. M\xe9todos potentes de mitigaci\xf3n de errores ya se est\xe1n desplegando como servicio, demostrando la fortaleza de la arquitectura QCSC. Por ejemplo:'}),"\n",(0,s.jsxs)(a.ul,{children:["\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsxs)(a.p,{children:["El ",(0,s.jsx)(a.a,{href:"/guides/algorithmiq-tem",children:"Tensor Network Error Mitigation"})," (TEM) de Algorithmiq trata el ruido en el posprocesamiento de software y utiliza recursos cl\xe1sicos de HPC para extender el alcance de las QPU actuales."]}),"\n"]}),"\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsxs)(a.p,{children:["El ",(0,s.jsx)(a.a,{href:"/guides/qedma-qesem",children:"Quantum Error Suppression and Error Mitigation"})," (QESEM) de Qedma combina la supresi\xf3n de errores a nivel de hardware con la mitigaci\xf3n de errores para mejorar la fiabilidad de las computaciones cu\xe1nticas a gran escala."]}),"\n"]}),"\n"]}),"\n"]}),"\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsx)(a.p,{children:"Democratizaci\xf3n del acceso: Hacer que estos potentes sistemas h\xedbridos sean accesibles a una amplia audiencia es la clave para acelerar la innovaci\xf3n. Esto ya se est\xe1 logrando mediante la instalaci\xf3n f\xedsica de sistemas cu\xe1nticos en centros HPC y la publicaci\xf3n de plugins de Slurm para una integraci\xf3n fluida. Para simplificar esta integraci\xf3n, ambas empresas han publicado plugins de Slurm para que las cargas de trabajo cu\xe1nticas puedan gestionarse con schedulers HPC est\xe1ndar. Adem\xe1s, pilas de software integrales como Qiskit proporcionan un entorno de runtime basado en la nube para la ejecuci\xf3n de circuitos cu\xe1nticos con baja latencia, que orquesta tareas h\xedbridas complejas y proporciona herramientas para compilaci\xf3n, optimizaci\xf3n y mitigaci\xf3n de errores. El acceso abierto al hardware cu\xe1ntico y los paquetes de software de c\xf3digo abierto desempe\xf1ar\xe1n sin duda un papel decisivo en esto."}),"\n"]}),"\n"]}),"\n",(0,s.jsx)(a.h2,{id:"ibms-outlook-for-the-future",children:"Perspectiva de IBM para el futuro"}),"\n",(0,s.jsxs)(a.p,{children:["La ",(0,s.jsx)(a.a,{href:"https://www.ibm.com/quantum/hardware#roadmap",children:"IBM Quantum Development Roadmap"})," ilustra bien esta visi\xf3n general y estas grandes ideas."]}),"\n",(0,s.jsx)(a.p,{children:(0,s.jsx)(a.img,{alt:"The IBM Quantum Development Roadmap",src:n(9239).A+"",width:"960",height:"536"})}),"\n",(0,s.jsx)(a.p,{children:'La hoja de ruta de hardware cu\xe1ntico de IBM est\xe1 impulsada por el enfoque en una mayor escala de qubits y mejor conectividad. La serie Nighthawk (2025\u20132028) utiliza una nueva arquitectura de rejilla cuadrada para mejorar la conectividad, mientras que el procesador Loon (2025) introduce "acopladores c" para permitir la conectividad no local de qubits, crucial para la computaci\xf3n cu\xe1ntica tolerante a fallos (FTQC). Esta hoja de ruta culmina en los sistemas IBM Quantum Starling (2029) y Blue Jay (2033+), dise\xf1ados para computaciones tolerantes a fallos a gran escala con millones de puertas y miles de qubits l\xf3gicos.'}),"\n",(0,s.jsx)(a.p,{children:"La estrategia de software y middleware se basa en cuatro objetivos fundamentales: ejecuci\xf3n precisa, orquestaci\xf3n de cargas de trabajo, descubrimiento de nuevos algoritmos y su aplicaci\xf3n a casos de uso espec\xedficos. La hoja de ruta incluye mejoras continuas como circuitos din\xe1micos a escala de utilidad (2025) y nuevas herramientas de perfilado (2026) para una ejecuci\xf3n eficiente. Para la orquestaci\xf3n de cargas de trabajo, la C-API (2025) y futuros aceleradores de flujos de trabajo (2027) integrar\xe1n la computaci\xf3n cu\xe1ntica y la computaci\xf3n cl\xe1sica de alto rendimiento (HPC). Adem\xe1s, IBM\xae introducir\xe1 herramientas de mapeo de utilidad (2026) y nuevas bibliotecas de circuitos (2029) para facilitar el descubrimiento y la aplicaci\xf3n de nuevos algoritmos."}),"\n",(0,s.jsx)(a.h2,{id:"summary",children:"Resumen"}),"\n",(0,s.jsx)(a.p,{children:"Hemos explorado la visi\xf3n general y las grandes ideas detr\xe1s del objetivo QCSC y hemos examinado la hoja de ruta de IBM para el desarrollo e innovaci\xf3n en computaci\xf3n cu\xe1ntica. Este viaje, como hemos visto, es un marat\xf3n, no un sprint. Aunque IBM se ha comprometido a entregar computadores cu\xe1nticos cada vez m\xe1s potentes, nuestro progreso es solo una parte de la ecuaci\xf3n. Es crucial que la comunidad cu\xe1ntica contin\xfae desarrollando nuevos algoritmos, allanando as\xed el camino para aplicaciones que realmente lleven la computaci\xf3n cu\xe1ntica \xfatil al mundo."}),"\n",(0,s.jsx)(a.p,{children:"Para lograr esto, debemos colaborar. Esto significa establecer problemas de benchmarking estandarizados con la ayuda de expertos cl\xe1sicos para asegurar relevancia y equidad. Tambi\xe9n requiere la publicaci\xf3n de m\xe9todos detallados y conjuntos de datos para la reproducibilidad, as\xed como el mantenimiento de clasificaciones abiertas para seguir nuestro progreso colectivo."}),"\n",(0,s.jsx)(a.p,{children:"Nunca ha habido un momento m\xe1s emocionante para ser parte de esta comunidad. Al adoptar estas mejores pr\xe1cticas y continuar nuestra exploraci\xf3n, podemos realizar juntos el potencial completo de la ventaja cu\xe1ntica."})]})}function u(e={}){const{wrapper:a}={...(0,o.R)(),...e.components};return a?(0,s.jsx)(a,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},44186(e,a,n){n.d(a,{A:()=>i});const i=n.p+"assets/images/advantage-f3e3886edc40357d426761d1573f7125.avif"},9239(e,a,n){n.d(a,{A:()=>i});const i=n.p+"assets/images/roadmap-7924495a92bb35df92784d3c36f8d468.avif"},28453(e,a,n){n.d(a,{R:()=>r,x:()=>c});var i=n(96540);const s={},o=i.createContext(s);function r(e){const a=i.useContext(o);return i.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function c(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),i.createElement(o.Provider,{value:a},e.children)}}}]);